    downloadBootIsoFile: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /** @description The Boot ISO's id. Anything that is not a Boot ISO id is `404` before a path is built, so the route can only read a Boot ISO file. */
                id: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The whole ISO. */
            200: {
                headers: {
                    "Accept-Ranges"?: "bytes";
                    "Cache-Control"?: "no-cache";
                    [name: string]: unknown;
                };
                content: {
                    "application/x-iso9660-image": string;
                };
            };
            /** @description The requested byte range; several ranges come as `multipart/byteranges`. */
            206: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/x-iso9660-image": string;
                    "multipart/byteranges": string;
                };
            };
            /** @description Not modified since `If-Modified-Since`. */
            304: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Not a Boot ISO id, or the Boot ISO has no file. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
            /** @description An `If-Unmodified-Since` precondition failed. */
            412: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description The requested range cannot be satisfied. */
            416: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
            default: components["responses"]["Error"];
        };
    };
